),
sheet as (
  select s.src, s.col, s.metric,
         ('20' || split_part(p, ':', 1))::date as week_start, split_part(p, ':', 2)::numeric as sheet_value
  from series s cross join lateral regexp_split_to_table(s.pts, ' ') as p
),
raw as (
  select 'mm'::text as src, 'linkedin'::text as col, e.key as metric, w.week_start,
         case when jsonb_typeof(e.value) = 'object' then e.value->>'value' else e.value #>> '{}' end as r
  from myntmore.mm_weekly_data w cross join lateral jsonb_each(case when jsonb_typeof(w.linkedin) = 'object' then w.linkedin else '{}'::jsonb end) e
  union all
  select 'mm', 'website', e.key, w.week_start,
         case when jsonb_typeof(e.value) = 'object' then e.value->>'value' else e.value #>> '{}' end
  from myntmore.mm_weekly_data w cross join lateral jsonb_each(case when jsonb_typeof(w.website) = 'object' then w.website else '{}'::jsonb end) e
  union all
  select 'tj', 'youtube', e.key, w.week_start,
         case when jsonb_typeof(e.value) = 'object' then e.value->>'value' else e.value #>> '{}' end
  from myntmore.tj_weekly_data w cross join lateral jsonb_each(case when jsonb_typeof(w.youtube) = 'object' then w.youtube else '{}'::jsonb end) e
  union all
  select 'tj', 'email_newsletter', e.key, w.week_start,
         case when jsonb_typeof(e.value) = 'object' then e.value->>'value' else e.value #>> '{}' end
  from myntmore.tj_weekly_data w cross join lateral jsonb_each(case when jsonb_typeof(w.email_newsletter) = 'object' then w.email_newsletter else '{}'::jsonb end) e
  union all
  select 'sales', 'meeting_tracker', e.key, w.week_start,
         case when jsonb_typeof(e.value) = 'object' then e.value->>'value' else e.value #>> '{}' end
  from myntmore.sales_weekly_data w cross join lateral jsonb_each(case when jsonb_typeof(w.meeting_tracker) = 'object' then w.meeting_tracker else '{}'::jsonb end) e
  union all
  select 'sales', 'cold_email', e.key, w.week_start,
         case when jsonb_typeof(e.value) = 'object' then e.value->>'value' else e.value #>> '{}' end
  from myntmore.sales_weekly_data w cross join lateral jsonb_each(case when jsonb_typeof(w.cold_email) = 'object' then w.cold_email else '{}'::jsonb end) e
  union all
  -- Total Meetings Booked (SO40) is only stored on newer weeks; older ones are the sum of its parts
  select 'sales', 'meeting_tracker', 'SO40', w.week_start, sum(case when x.r ~ '^-?[0-9]+(\.[0-9]+)?$' then x.r::numeric end)::text
  from myntmore.sales_weekly_data w
  cross join lateral (
    select case when jsonb_typeof(e.value) = 'object' then e.value->>'value' else e.value #>> '{}' end as r
    from jsonb_each(case when jsonb_typeof(w.meeting_tracker) = 'object' then w.meeting_tracker else '{}'::jsonb end) e where e.key in ('SO36','SO37','SO38','SO39','SO56')
  ) x
  where not (w.meeting_tracker ? 'SO40')
  group by w.week_start
),
app as (
  select src, col, metric, week_start,
         case when r ~ '^-?[0-9]+(\.[0-9]+)?$' then r::numeric end as app_value
  from raw
)
select s.src, s.col, s.metric, s.week_start, s.sheet_value, a.app_value,
       case when a.app_value is null then 'MISSING IN APP' else 'DIFFERENT' end as problem
from sheet s
left join app a on a.src = s.src and a.col = s.col and a.metric = s.metric and a.week_start = s.week_start
where a.app_value is null
   or abs(a.app_value - s.sheet_value) > case when s.metric in ('TJP10','MMW04') then 1 else 0.5 end
order by s.src, s.col, s.metric, s.week_start;
